message.content:
{
  "lines": [
    {
      "text": "— 93 —"
    },
    {
      "text": "die Tauben wieder herein und thaten freund="
    },
    {
      "text": "lich: „Aschenputtel, sollen wir dir die Wicken"
    },
    {
      "text": "lesen?“ „Ja, —"
    },
    {
      "text": "die schlechten ins Kröpfchen,"
    },
    {
      "text": "die guten ins Töpfchen.“"
    },
    {
      "text": "Pick, pick! pick, pick! gings so geschwind, als"
    },
    {
      "text": "wären zwölf Hände da. Und als sie fertig wa="
    },
    {
      "text": "ren, sagten die Tauben: „Aschenputtel, willst"
    },
    {
      "text": "du auch auf den Ball gehen und tanzen.“ —"
    },
    {
      "text": "„O du mein Gott, sagte es, wie kann ich in"
    },
    {
      "text": "meinen schmutzigen Kleidern hingehen?“ —"
    },
    {
      "text": "„Geh zu dem Bäumlein auf deiner Mutter"
    },
    {
      "text": "Grab, schüttele daran und wünsche dir schöne"
    },
    {
      "text": "Kleider, komm aber vor Mitternacht wieder.“"
    },
    {
      "text": "— da ging Aschenputtel hinaus, schüttelte das"
    },
    {
      "text": "Bäumlein und sprach:"
    },
    {
      "text": "„Bäumlein rüttel und schüttel dich,"
    },
    {
      "text": "wirf schöne Kleider herab für mich!“"
    },
    {
      "text": "Kaum hatte es das ausgesagt, da lag ein präch="
    },
    {
      "text": "tig silbern Kleid vor ihm, Perlen, seidene"
    },
    {
      "text": "Strümpfe mit silbernen Zwickeln und silberne"
    },
    {
      "text": "Pantoffel und was sonst dazu gehörte. Aschen="
    },
    {
      "text": "puttel trug alles nach Haus, und als es sich"
    },
    {
      "text": "gewaschen und angezogen hatte, da war es so"
    },
    {
      "text": "schön wie eine Rose, die der Thau gewaschen"
    },
    {
      "text": "hat. Und wie es vor die Hausthüre kam, so"
    },
    {
      "text": "stand da ein Wagen mit sechs federgeschmück="
    },
    {
      "text": "ten Rappen und Bediente dabei in Blau und"
    }
  ],
  "script": "fraktur",
  "notes": ""
}

